package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import org.apache.commons.lang3.ArrayUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ClassUtils_toClass_TriageGen1Test {



    @Test
    public void testToClass_ValidObjects() {
        Object[] input = new Object[]{"String", 123, 45.67};
        Class<?>[] expected = new Class<?>[]{String.class, Integer.class, Double.class};
        Class<?>[] actual = ClassUtils.toClass(input);

        Assert.assertNotNull(actual);
        Assert.assertEquals(expected.length, actual.length);
        for (int i = 0; i < expected.length; i++) {
            Assert.assertEquals("Class mismatch at index " + i, expected[i], actual[i]);
        }
    }




}

package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import org.apache.commons.lang3.ArrayUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class ClassUtils_toClass_TriageGen1Test {





    @Test
    public void testToClass_WithNullElements() {
        Object[] input = new Object[]{"String", null, 123};
        Class<?>[] expected = new Class<?>[]{String.class, null, Integer.class};
        Class<?>[] actual = ClassUtils.toClass(input);

        Assert.assertNotNull(actual);
        Assert.assertEquals(expected.length, actual.length);
        Assert.assertEquals(expected[0], actual[0]);
        Assert.assertNull("Null element in input should result in null in output array", actual[1]);
        Assert.assertEquals(expected[2], actual[2]);
    }


}

